  def icon(name, size: 16, css: nil, label: nil, stroke_width: 2)
    paths = ICONS.fetch(name.to_s) { raise ArgumentError, "unknown icon #{name}" }
    attrs = { width: size, height: size, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", stroke_width: stroke_width,
              stroke_linecap: "round", stroke_linejoin: "round", class: ["icon", css].compact.join(" ") }
    attrs.merge!(role: "img", "aria-label": label) if label
    attrs["aria-hidden"] = "true" unless label
    tag.svg(paths.html_safe, **attrs)
  end
